<template><div class="page-container"><div class="hero"><div><h2>AI 公文摘要与审批助手</h2><p>提炼核心要点，结合历史审批习惯与学校规章生成意见草稿</p></div><el-tag effect="dark" type="primary">AI 辅助结果仅供参考</el-tag></div><el-row :gutter="20"><el-col :span="8"><el-card shadow="never"><template #header>选择公文</template><el-form label-position="top"><el-form-item label="当前审批人ID"><el-input-number v-model="userId" :min="1" @change="load"/></el-form-item><el-form-item label="待审批公文"><el-select v-model="docId" filterable placeholder="请选择"><el-option v-for="d in docs" :key="d.docId" :label="d.title" :value="d.docId"/></el-select></el-form-item><el-form-item label="本次适用的学校规章（可选）"><el-input v-model="schoolRules" type="textarea" :rows="4" placeholder="粘贴与本公文相关的制度条款；留空时 AI 不会虚构制度依据"/></el-form-item></el-form><el-empty v-if="!docs.length" description="当前没有待审批公文"/><template v-if="selected"><el-descriptions :column="1" border><el-descriptions-item label="类型">{{selected.docType}}</el-descriptions-item><el-descriptions-item label="发起人">{{selected.initiatorId}}</el-descriptions-item></el-descriptions><p class="content">{{selected.content}}</p></template><el-button type="primary" :disabled="!docId" :loading="loading==='summary'" @click="generate('summary')">生成要点摘要</el-button><el-button :disabled="!docId" :loading="loading==='recommend'" @click="generate('recommend')">生成审批建议</el-button></el-card></el-col><el-col :span="16"><el-card shadow="never"><template #header><div class="result-title"><span>AI 生成结果</span><el-button link :disabled="!result" @click="copy">复制结果</el-button></div></template><el-skeleton v-if="loading" :rows="8" animated/><el-input v-else-if="result" v-model="result" type="textarea" :rows="22" resize="vertical"/><el-empty v-else description="选择公文后生成摘要或审批建议"/></el-card></el-col></el-row></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{aiApprovalAPI,documentAPI}from'@/api/getData.js';const userId=ref(1),docs=ref([]),docId=ref(),result=ref(''),loading=ref(''),schoolRules=ref('');const selected=computed(()=>docs.value.find(v=>v.docId===docId.value));const load=async()=>{const r=await documentAPI.pending(userId.value);if(r&&r!==-1){docs.value=r.data||[];docId.value=docs.value[0]?.docId}};const generate=async type=>{loading.value=type;try{const r=type==='summary'?await aiApprovalAPI.summary(docId.value):await aiApprovalAPI.recommend(docId.value,{schoolRules:schoolRules.value});if(r&&r!==-1)result.value=r.data||''}finally{loading.value=''}};const copy=async()=>{await navigator.clipboard.writeText(result.value);ElMessage.success('已复制')};onMounted(load);</script>
<style scoped>.page-container{padding:24px;background:#f5f7fa;min-height:100vh}.hero{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.hero h2{margin:0}.hero p{color:#909399}.content{padding:12px;background:#f5f7fa;white-space:pre-wrap;max-height:220px;overflow:auto}.result-title{display:flex;justify-content:space-between}.el-button{margin-top:14px}</style>
